func newWorkstreamStep() *sqlgraph.Step {
	return sqlgraph.NewStep(
		sqlgraph.From(Table, FieldID),
		sqlgraph.To(WorkstreamInverseTable, FieldID),
		sqlgraph.Edge(sqlgraph.M2O, false, WorkstreamTable, WorkstreamColumn),
	)
}
func newWorkActionStep() *sqlgraph.Step {
	return sqlgraph.NewStep(
		sqlgraph.From(Table, FieldID),
		sqlgraph.To(WorkActionInverseTable, FieldID),
		sqlgraph.Edge(sqlgraph.M2O, false, WorkActionTable, WorkActionColumn),
	)
}
func newPullRequestStep() *sqlgraph.Step {
	return sqlgraph.NewStep(
		sqlgraph.From(Table, FieldID),
		sqlgraph.To(PullRequestInverseTable, FieldID),
		sqlgraph.Edge(sqlgraph.M2O, false, PullRequestTable, PullRequestColumn),
	)
}
func newTicketStep() *sqlgraph.Step {
	return sqlgraph.NewStep(
		sqlgraph.From(Table, FieldID),
		sqlgraph.To(TicketInverseTable, FieldID),
		sqlgraph.Edge(sqlgraph.M2O, false, TicketTable, TicketColumn),
	)
}
func newLatestEvidenceStep() *sqlgraph.Step {
	return sqlgraph.NewStep(
		sqlgraph.From(Table, FieldID),
		sqlgraph.To(LatestEvidenceInverseTable, FieldID),
		sqlgraph.Edge(sqlgraph.M2O, false, LatestEvidenceTable, LatestEvidenceColumn),
	)
}
func newLinksStep() *sqlgraph.Step {
	return sqlgraph.NewStep(
		sqlgraph.From(Table, FieldID),
		sqlgraph.To(LinksInverseTable, FieldID),
		sqlgraph.Edge(sqlgraph.O2M, true, LinksTable, LinksColumn),
	)
}
